solutionTSQL:
-- 1-ci Üsul: NOT EXISTS (Böyük cədvəllərdə ən optimal):
SELECT c.CustomerID, c.FullName
FROM dbo.Customers c
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.Claims cl WHERE cl.CustomerID = c.CustomerID
);

