solutionPostgres:
-- PostgreSQL-də də eyni standart:
SELECT c.customer_id, c.full_name
FROM core.customers c
WHERE NOT EXISTS (
    SELECT 1 FROM core.claims cl WHERE cl.customer_id = c.customer_id
);
